function p = legpp_legen_nor(x, m)
% LEGPP_LEGEN_NOR  Second derivative of L2-normalized Legendre polynomial.
% Convention: L_m = sqrt((2m+1)/2)*P_m, normalized on [-1,1].
% Coefficients auto-generated via recurrence and verified against FD.
switch m
    case 0
        p = zeros(size(x));
