        p = zeros(size(x));
    case 2
        p = ones(size(x))*4.74341649025257;
    case 3
        p = 28.0624304008046*x;
    case 4
        p = 111.369318036881*x.^2 - 15.9099025766973;
    case 5
        p = 369.370241086095*x.^3 - 123.123413695365*x;
    case 6
        p = 1104.25641341244*x.^4 - 602.321680043148*x.^2 + 33.4623155579526;
    case 7
        p = 3084.02032535253*x.^5 - 2372.32332719425*x.^3 + 323.498635526489*x;
    case 8
        p = 8207.97587822833*x.^6 - 8207.97587822833*x.^4 + 1894.14827959115*x.^2 - 57.3984327148834;
    case 9
        p = 21073.6271829622*x.^7 - 26032.1276966004*x.^5 + 8677.3758988668*x.^3 - 667.490453758984*x;
    case 10
        p = 52618.1716615009*x.^8 - 77542.5687643171*x.^6 + 34209.956807787*x.^4 - 4561.32757437159*x.^2 + 87.7178379686845;
    case 11
        p = 128489.254519571*x.^9 - 220267.293462122*x.^7 + 121726.662176436*x.^5 - 23867.9729757717*x.^3 + 1193.39864878858*x;
    case 12
        p = 308106.408615955*x.^10 - 602816.88642252*x.^8 + 401877.92428168*x.^6 - 105757.348495179*x.^4 + 9331.53074957462*x.^2 - 124.420409994328;
    case 13
        p = 727712.664355106*x.^11 - 1600967.86158123*x.^9 + 1252931.36993314*x.^7 - 417643.789977713*x.^5 + 54953.1302602254*x.^3 - 1939.52224447854*x;
    case 14
        p = 1696912.96554332*x.^12 - 4148009.47132811*x.^10 + 3733208.5241953*x.^8 - 1514925.19822418*x.^6 + 270522.356825746*x.^4 - 17085.6225363629*x.^2 + 167.506103297676;
    case 15
        p = 3913776.86331495*x.^13 - 10526710.1840885*x.^11 + 10721649.2615716*x.^9 - 5146391.64555437*x.^7 + 1174719.83213741*x.^5 - 111878.079251182*x.^3 + 2944.15998029427*x;
    case 16
        p = 8941406.56610149*x.^14 - 26247354.758556*x.^12 + 29867679.5528396*x.^10 - 16593155.3071331*x.^8 + 4646083.48599727*x.^6 - 606010.889477904*x.^4 + 28857.6614037097*x.^2 - 216.974897772254;
    case 17
        p = 20258420.235028*x.^15 - 64458609.8387254*x.^13 + 81093089.7971061*x.^11 - 51265746.4234579*x.^9 + 17088582.1411526*x.^7 - 2870881.79971364*x.^5 + 208034.913022728*x.^3 - 4245.61046985158*x;
    otherwise
        error('legpp_legen_nor: degree m=%d not supported (max 17)', m);
end
end